    title: "Flask应用基础",
    content: `# Flask应用基础\n\n## 一、Flask实例创建\n\n### 基本创建方式\n\n\`\`\`python\nfrom flask import Flask\n\n# 创建应用实例\napp = Flask(__name__)\n\n# __name__参数作用：\n# 1. 确定应用根路径，用于查找模板和静态文件\n# 2. 用于Flask扩展识别应用\n\n# 显式指定模板和静态文件路径\napp = Flask(\n    __name__,\n    template_folder='templates',  # 默认templates\n    static_folder='static',       # 默认static\n    static_url_path='/static',    # 静态文件URL前缀\n    instance_relative_config=True  # 配置文件相对于instance文件夹\n)\n\n\`\`\`\n\n### 应用配置\n\n\`\`\`python\n# 直接配置\napp.config['SECRET_KEY'] = 'your-secret-key'\napp.config['DEBUG'] = True\n\n# 从对象配置\nclass Config:\n    SECRET_KEY = 'your-secret-key'\n    SQLALCHEMY_DATABASE_URI = 'sqlite:///app.db'\n\nclass DevelopmentConfig(Config):\n    DEBUG = True\n\nclass ProductionConfig(Config):\n    DEBUG = False\n\napp.config.from_object(DevelopmentConfig)\n\n# 从配置文件\napp.config.from_pyfile('config.py')\n\n# 从环境变量\nimport os\napp.config['SECRET_KEY'] = os.environ.get('SECRET_KEY')\n\n# 使用python-dotenv\n# pip install python-dotenv\nfrom dotenv import load_dotenv\nload_dotenv()\napp.config['SECRET_KEY'] = os.getenv('SECRET_KEY')\n\n\`\`\`\n\n## 二、路由注册\n\n### @app.route装饰器\n\n\`\`\`python\nfrom flask import Flask\napp = Flask(__name__)\n\n# 基本路由\n@app.route('/')\ndef index():\n    return 'Index Page'\n\n# 多个URL路由到同一视图\n@app.route('/about')\n@app.route('/about-us')\ndef about():\n    return 'About Page'\n\n# 接受HTTP方法\n@app.route('/login', methods=['GET', 'POST'])\ndef login():\n    from flask import request\n    if request.method == 'POST':\n        return 'Do login'\n    return 'Login Form'\n\n\`\`\`\n\n### add_url_rule方法\n\n\`\`\`python\ndef hello():\n    return 'Hello'\n\n# 等价于 @app.route('/hello')\napp.add_url_rule('/hello', view_func=hello, endpoint='hello')\n\n# 指定endpoint名称\napp.add_url_rule(\n    '/user/<int:id>',\n    view_func=show_user,\n    endpoint='user_profile',\n    methods=['GET']\n)\n\n\`\`\`\n\n## 三、变量规则\n\n| 转换器 | 说明 | 示例 |\n|--------|------|------|\n| string | 默认，接受无斜杠文本 | /user/<username> |\n| int | 接受正整数 | /post/<int:post_id> |\n| float | 接受正浮点数 | /price/<float:amount> |\n| path | 类似string，但接受斜杠 | /path/<path:subpath> |\n| uuid | 接受UUID字符串 | /item/<uuid:item_id> |\n\n\`\`\`python\n@app.route('/user/<username>')\ndef show_user(username):\n    return f'User: {username}'\n\n@app.route('/post/<int:post_id>')\ndef show_post(post_id):\n    # post_id已经是整数类型\n    return f'Post ID: {post_id}'\n\n@app.route('/path/<path:subpath>')\ndef show_subpath(subpath):\n    return f'Subpath: {subpath}'\n# 匹配: /path/a/b/c/d\n\n# 自定义转换器\nfrom werkzeug.routing import BaseConverter\n\nclass ListConverter(BaseConverter):\n    def to_python(self, value):\n        return value.split('+')\n\n    def to_url(self, values):\n        return '+'.join(BaseConverter.to_url(self, value) for value in values)\n\napp.url_map.converters['list'] = ListConverter\n\n@app.route('/tags/<list:tags>')\ndef show_tags(tags):\n    return f'Tags: {tags}'\n# 匹配: /tags/python+flask+django\n\`\`\`\n\n## 四、URL构建url_for\n\n\`\`\`python\nfrom flask import Flask, url_for\n\napp = Flask(__name__)\n\n@app.route('/')\ndef index():\n    return 'Index'\n\n@app.route('/user/<username>')\ndef profile(username):\n    return f'Profile: {username}'\n\nwith app.test_request_context():\n    print(url_for('index'))  # /\n    print(url_for('profile', username='john'))  # /user/john\n    print(url_for('profile', username='john', page=2))  # /user/john?page=2\n    print(url_for('static', filename='style.css'))  # /static/style.css\n\n# 在视图中使用\nfrom flask import redirect\n\n@app.route('/redirect-example')\ndef redirect_example():\n    return redirect(url_for('profile', username='john'))\n\n# 在模板中使用\n# <a href=\\"{{ url_for('profile', username='john') }}\\">John Profile</a>\n\n\`\`\`\n\n## 五、HTTP方法处理\n\n\`\`\`python\nfrom flask import Flask, request, render_template, redirect, url_for\napp = Flask(__name__)\n\n@app.route('/login', methods=['GET', 'POST'])\ndef login():\n    if request.method == 'POST':\n        username = request.form.get('username')\n        password = request.form.get('password')\n        # 验证逻辑\n        return redirect(url_for('dashboard'))\n    return render_template('login.html')\n\n# 也可以分开处理\n@app.get('/api/users')\ndef get_users():\n    return {'users': []}\n\n@app.post('/api/users')\ndef create_user():\n    data = request.get_json()\n    return {'id': 1}, 201\n\n@app.put('/api/users/<int:id>')\ndef update_user(id):\n    return {'id': id}\n\n@app.delete('/api/users/<int:id>')\ndef delete_user(id):\n    return '', 204\n\n# 常用HTTP方法装饰器\n# @app.get() - GET\n# @app.post() - POST\n# @app.put() - PUT\n# @app.patch() - PATCH\n# @app.delete() - DELETE\n\n\`\`\`\n\n## 六、运行应用\n\n\`\`\`python\n# 开发模式\nif __name__ == '__main__':\n    app.run(\n        host='127.0.0.1',  # 监听地址\n        port=5000,         # 端口\n        debug=True,        # 调试模式（自动重载、错误页面）\n        use_reloader=True  # 自动重载\n    )\n\n# 命令行运行\n# flask run\n# flask run --host=0.0.0.0 --port=8000 --debug\n\n# 环境变量配置\n# FLASK_APP=app.py\n# FLASK_ENV=development\n# FLASK_DEBUG=1\n\n\`\`\`\n\n## 七、最佳实践\n\n1. **合理命名endpoint**：使用有意义的名称，方便url_for\n2. **尾斜杠规则**：/projects和/projects/是不同URL，建议带尾斜杠\n3. **HTTP方法显式声明**：明确指定允许的methods\n4. **使用url_for构建URL**：避免硬编码URL\n5. **配置使用对象和环境变量**：不要硬编码敏感信息\n6. **变量转换器明确类型**：使用int/float等转换器\n\n## 八、常见坑点\n\n\`\`\`python\n# 坑1：尾斜杠问题\n@app.route('/projects')\ndef projects():\n    return 'Projects'\n# 访问 /projects/ 会404\n\n@app.route('/about/')\ndef about():\n    return 'About'\n# 访问 /about 会自动重定向到 /about/\n\n# 坑2：endpoint重复\n@app.route('/user/<int:id>', endpoint='user_detail')\ndef get_user(id):\n    pass\n\n@app.route('/user/<int:id>/edit', endpoint='user_detail')  # 重复！\ndef edit_user(id):\n    pass\n\n# 坑3：url_for参数不匹配\n@app.route('/user/<username>')\ndef profile(username):\n    pass\n\nurl_for('profile')  # 错误，缺少username参数\nurl_for('profile', username='john')  # 正确\n\n\`\`\``
